import math


def max_volume(s):
    """Return maximum volume of a cuboid with integer sides summing to s.

    The sum `s` is length + width + height. Sides are positive integers;
    the product is maximized when sides are as equal as possible.
    """
    if s < 0:
        return 0
    n = math.floor(s)
    if n < 3:
        return 0
    q, r = divmod(n, 3)
    if r == 0:
        return q * q * q
    if r == 1:
        return q * q * (q + 1)
    return q * (q + 1) * (q + 1)
